-- KO-446: Chapter 11 quiz/source quality repair.
-- Replace the small generic pool with five distinct, lesson-specific checks.
-- Examples are educational and do not predict or recommend trades.
BEGIN;

WITH source_map(slug, source_code) AS (VALUES
  ('decision-multicandle-context','CH08-OJK-CAPITAL'),
  ('decision-volume-confirmation','CH08-IDX-TRADING'),
  ('decision-zones-false-breakouts','CH08-OJK-CAPITAL'),
  ('decision-timeframe-comparison','CH08-IDX-TRADING'),
  ('decision-risk-reward','OJK-ADV-001'),
  ('decision-position-sizing','OJK-ADV-001'),
  ('decision-bias-and-narratives','OJK-003'),
  ('decision-thesis-invalidation','OJK-ADV-001')
)
INSERT INTO public.lesson_sources (lesson_id, source_id, relevance_type, citation_label, is_primary, display_order)
SELECT l.id, s.id, 'primary', s.source_code, TRUE, 10
FROM source_map m
JOIN public.lessons l ON l.slug=m.slug AND l.is_published
JOIN public.sources s ON s.source_code=m.source_code
ON CONFLICT (lesson_id, source_id) DO UPDATE
SET relevance_type=EXCLUDED.relevance_type,
    citation_label=EXCLUDED.citation_label,
    is_primary=EXCLUDED.is_primary,
    display_order=EXCLUDED.display_order;

-- Retire the previous three-question and generic cross-lesson pool. Historical
-- rows remain available for audit, but only the authored five-question pool is
-- eligible for learners.
UPDATE public.content_variants v
SET is_active=FALSE
FROM public.lessons l
JOIN public.topics t ON t.id=l.topic_id
WHERE v.lesson_id=l.id
  AND t.chapter='Decision Analysis Lab'
  AND l.is_published
  AND v.variant_type='question'
  AND v.is_active;

WITH authored(slug, questions) AS (VALUES
('decision-multicandle-context', $json$[
  {"en":{"type":"multiple_choice","question":"Four candles rise, pause, reject a higher level, then close near the starting zone. What is supported?","options":["The sequence shows changing reactions that need context","The next candle must rise","The rejection guarantees a reversal","One candle proves the whole trend"],"answer":"The sequence shows changing reactions that need context","explanation":"A sequence describes observed reactions; it does not guarantee the next move."},"id":{"type":"multiple_choice","question":"Empat candle naik, berhenti, menolak level lebih tinggi, lalu ditutup dekat zona awal. Apa yang didukung?","options":["Rangkaian menunjukkan reaksi yang berubah dan membutuhkan konteks","Candle berikutnya pasti naik","Penolakan menjamin pembalikan","Satu candle membuktikan seluruh tren"],"answer":"Rangkaian menunjukkan reaksi yang berubah dan membutuhkan konteks","explanation":"Rangkaian menggambarkan reaksi yang diamati; bukan jaminan pergerakan berikutnya."}},
  {"en":{"type":"multiple_choice","question":"A long upper wick appears after several rising candles. What is the most careful description?","options":["Higher prices were rejected during that interval","A reversal is guaranteed","Buyers have disappeared forever","The company value has fallen"],"answer":"Higher prices were rejected during that interval","explanation":"A wick records a within-interval reaction, not a forecast."},"id":{"type":"multiple_choice","question":"Sumbu atas panjang muncul setelah beberapa candle naik. Apa deskripsi paling hati-hati?","options":["Harga lebih tinggi ditolak dalam interval itu","Pembalikan dijamin","Pembeli menghilang selamanya","Nilai perusahaan menurun"],"answer":"Harga lebih tinggi ditolak dalam interval itu","explanation":"Sumbu mencatat reaksi dalam interval, bukan ramalan."}},
  {"en":{"type":"multiple_choice","question":"What should be checked before calling a candle sequence a trend?","options":["Timeframe, surrounding price action, and later evidence","Only the colour of the last candle","A confident social-media caption","The largest candle in isolation"],"answer":"Timeframe, surrounding price action, and later evidence","explanation":"Context makes the description more disciplined without making it certain."},"id":{"type":"multiple_choice","question":"Apa yang perlu diperiksa sebelum menyebut rangkaian candle sebagai tren?","options":["Timeframe, pergerakan sekitar, dan bukti setelahnya","Hanya warna candle terakhir","Caption media sosial yang percaya diri","Candle terbesar secara terpisah"],"answer":"Timeframe, pergerakan sekitar, dan bukti setelahnya","explanation":"Konteks membuat deskripsi lebih disiplin tanpa menjadikannya pasti."}},
  {"en":{"type":"multiple_choice","question":"Two sequences have the same shape but different timeframes. What is safest to conclude?","options":["They may describe different levels of detail","They must have the same outcome","The longer timeframe is always correct","The shorter timeframe removes context"],"answer":"They may describe different levels of detail","explanation":"Aggregation changes what is visible; it does not settle the future."},"id":{"type":"multiple_choice","question":"Dua rangkaian memiliki bentuk sama tetapi timeframe berbeda. Apa kesimpulan paling aman?","options":["Keduanya mungkin menggambarkan tingkat detail berbeda","Hasilnya pasti sama","Timeframe lebih panjang selalu benar","Timeframe pendek menghapus konteks"],"answer":"Keduanya mungkin menggambarkan tingkat detail berbeda","explanation":"Agregasi mengubah apa yang terlihat; bukan menentukan masa depan."}},
  {"en":{"type":"multiple_choice","question":"What does multi-candle context improve most?","options":["The quality of the description","The certainty of a prediction","The guaranteed entry price","The accuracy of a rumour"],"answer":"The quality of the description","explanation":"More observations can improve language and questions, not certainty."},"id":{"type":"multiple_choice","question":"Apa yang paling ditingkatkan oleh konteks beberapa candle?","options":["Kualitas deskripsi","Kepastian ramalan","Harga masuk yang dijamin","Akurasi rumor"],"answer":"Kualitas deskripsi","explanation":"Lebih banyak pengamatan dapat memperbaiki bahasa dan pertanyaan, bukan kepastian."}}
]$json$::jsonb),
('decision-volume-confirmation', $json$[
  {"en":{"type":"multiple_choice","question":"A price move has unusually high volume. What is the best next question?","options":["What news, level, or event might explain the activity?","How can I copy it immediately?","Which price is guaranteed next?","Why does volume remove risk?"],"answer":"What news, level, or event might explain the activity?","explanation":"Unusual activity invites investigation; it does not prove direction."},"id":{"type":"multiple_choice","question":"Pergerakan harga memiliki volume sangat tinggi. Apa pertanyaan berikutnya?","options":["Berita, level, atau peristiwa apa yang mungkin menjelaskan aktivitas itu?","Bagaimana langsung menirunya?","Harga berikutnya mana yang dijamin?","Mengapa volume menghapus risiko?"],"answer":"Berita, level, atau peristiwa apa yang mungkin menjelaskan aktivitas itu?","explanation":"Aktivitas tidak biasa mengundang pemeriksaan; bukan bukti arah harga."}},
  {"en":{"type":"multiple_choice","question":"High volume proves a price move will continue.","options":["True","False","Only in a rising market","Only with a famous ticker"],"answer":"False","explanation":"Volume is context about past activity, not proof of the next outcome."},"id":{"type":"multiple_choice","question":"Volume tinggi membuktikan pergerakan harga akan berlanjut.","options":["Benar","Salah","Hanya di pasar naik","Hanya dengan ticker terkenal"],"answer":"Salah","explanation":"Volume adalah konteks aktivitas masa lalu, bukan bukti hasil berikutnya."}},
  {"en":{"type":"multiple_choice","question":"What should stay separate when reading volume?","options":["Observed activity and the forecast","Ticker and exchange","Candle and its date","Source and its title"],"answer":"Observed activity and the forecast","explanation":"Separating observation from forecast prevents overclaiming."},"id":{"type":"multiple_choice","question":"Apa yang harus tetap dipisahkan saat membaca volume?","options":["Aktivitas yang diamati dan ramalan","Ticker dan bursa","Candle dan tanggalnya","Sumber dan judulnya"],"answer":"Aktivitas yang diamati dan ramalan","explanation":"Memisahkan pengamatan dari ramalan mencegah klaim berlebihan."}},
  {"en":{"type":"multiple_choice","question":"A volume spike occurs while price moves sideways. What is supported?","options":["Participation changed; direction still needs evidence","A breakout is guaranteed","The asset is now risk-free","The close must be higher tomorrow"],"answer":"Participation changed; direction still needs evidence","explanation":"Activity can change without resolving direction."},"id":{"type":"multiple_choice","question":"Lonjakan volume terjadi saat harga bergerak mendatar. Apa yang didukung?","options":["Partisipasi berubah; arah masih membutuhkan bukti","Breakout dijamin","Aset kini bebas risiko","Penutupan besok pasti lebih tinggi"],"answer":"Partisipasi berubah; arah masih membutuhkan bukti","explanation":"Aktivitas dapat berubah tanpa menentukan arah."}},
  {"en":{"type":"multiple_choice","question":"Which comparison is more disciplined?","options":["Volume is a clue to investigate alongside price and context","Volume alone predicts the next candle","A large bar proves informed buyers","Low volume always means a bad asset"],"answer":"Volume is a clue to investigate alongside price and context","explanation":"Volume becomes useful when treated as one observation among several."},"id":{"type":"multiple_choice","question":"Perbandingan mana yang lebih disiplin?","options":["Volume adalah petunjuk untuk diperiksa bersama harga dan konteks","Volume saja memprediksi candle berikutnya","Bar besar membuktikan pembeli yang tahu","Volume rendah selalu berarti aset buruk"],"answer":"Volume adalah petunjuk untuk diperiksa bersama harga dan konteks","explanation":"Volume berguna jika diperlakukan sebagai satu pengamatan di antara beberapa hal."}}
]$json$::jsonb),
('decision-zones-false-breakouts', $json$[
  {"en":{"type":"multiple_choice","question":"Price briefly moves above a zone and closes back inside. What is careful?","options":["The breach and return are evidence to inspect, not a guaranteed reversal","The zone must hold forever","The next candle must fall","The exact zone price is known"],"answer":"The breach and return are evidence to inspect, not a guaranteed reversal","explanation":"A false breakout describes what happened; it does not settle what happens next."},"id":{"type":"multiple_choice","question":"Harga sebentar di atas zona lalu kembali masuk. Apa pembacaan hati-hati?","options":["Penembusan dan kembalinya harga adalah bukti untuk diperiksa, bukan pembalikan yang dijamin","Zona pasti bertahan selamanya","Candle berikutnya pasti turun","Harga zona tepat sudah diketahui"],"answer":"Penembusan dan kembalinya harga adalah bukti untuk diperiksa, bukan pembalikan yang dijamin","explanation":"False breakout menjelaskan apa yang terjadi; bukan menentukan yang berikutnya."}},
  {"en":{"type":"multiple_choice","question":"Support and resistance are better treated as what?","options":["Reaction areas","Magical exact prices","Guaranteed floors","Company fair value"],"answer":"Reaction areas","explanation":"Nearby reactions can cluster across a range."},"id":{"type":"multiple_choice","question":"Support dan resistance lebih tepat diperlakukan sebagai apa?","options":["Area reaksi","Harga tepat yang ajaib","Lantai yang dijamin","Nilai wajar perusahaan"],"answer":"Area reaksi","explanation":"Reaksi berdekatan dapat berkumpul dalam suatu rentang."}},
  {"en":{"type":"multiple_choice","question":"What should follow marking a reaction zone?","options":["Observe the breach, return, and later evidence","Assume a guaranteed bounce","Ignore the timeframe","Treat one touch as proof"],"answer":"Observe the breach, return, and later evidence","explanation":"A zone must be updated with new evidence."},"id":{"type":"multiple_choice","question":"Apa yang dilakukan setelah menandai zona reaksi?","options":["Amati penembusan, kembalinya harga, dan bukti setelahnya","Anggap pantulan dijamin","Abaikan timeframe","Anggap satu sentuhan sebagai bukti"],"answer":"Amati penembusan, kembalinya harga, dan bukti setelahnya","explanation":"Zona perlu diperbarui dengan bukti baru."}},
  {"en":{"type":"multiple_choice","question":"A price pierces a zone intraday but closes inside it. Which label is most precise?","options":["A test and return within the observed interval","A confirmed long-term breakout","A guaranteed reversal","A company announcement"],"answer":"A test and return within the observed interval","explanation":"The label should describe the observed interval without extending beyond it."},"id":{"type":"multiple_choice","question":"Harga menembus zona intraday tetapi ditutup di dalamnya. Label mana yang paling tepat?","options":["Uji dan kembali dalam interval yang diamati","Breakout jangka panjang yang terkonfirmasi","Pembalikan yang dijamin","Pengumuman perusahaan"],"answer":"Uji dan kembali dalam interval yang diamati","explanation":"Label harus menjelaskan interval yang diamati tanpa melampauinya."}},
  {"en":{"type":"multiple_choice","question":"Why can one touch of a zone be weak evidence?","options":["A single reaction does not establish a durable boundary","Every zone is imaginary","Price never reacts twice","The timeframe is irrelevant"],"answer":"A single reaction does not establish a durable boundary","explanation":"A zone is a working area, not a permanent promise."},"id":{"type":"multiple_choice","question":"Mengapa satu sentuhan zona bisa menjadi bukti yang lemah?","options":["Satu reaksi tidak membentuk batas yang bertahan","Setiap zona hanya imajinasi","Harga tidak pernah bereaksi dua kali","Timeframe tidak relevan"],"answer":"Satu reaksi tidak membentuk batas yang bertahan","explanation":"Zona adalah area kerja, bukan janji permanen."}}
]$json$::jsonb),
('decision-timeframe-comparison', $json$[
  {"en":{"type":"multiple_choice","question":"Why can a five-minute move look dramatic while a weekly chart looks ordinary?","options":["Each timeframe aggregates the same activity into different detail","The weekly chart deletes volatility","The five-minute chart guarantees a forecast","One chart must be wrong"],"answer":"Each timeframe aggregates the same activity into different detail","explanation":"A timeframe changes the observation lens, not historical events."},"id":{"type":"multiple_choice","question":"Mengapa pergerakan lima menit tampak dramatis sementara grafik mingguan biasa?","options":["Setiap timeframe mengagregasi aktivitas yang sama dengan detail berbeda","Grafik mingguan menghapus volatilitas","Grafik lima menit menjamin ramalan","Salah satu grafik pasti salah"],"answer":"Setiap timeframe mengagregasi aktivitas yang sama dengan detail berbeda","explanation":"Timeframe mengubah lensa pengamatan, bukan peristiwa historis."}},
  {"en":{"type":"multiple_choice","question":"A longer timeframe removes market risk.","options":["True","False","Only for large companies","Only after a breakout"],"answer":"False","explanation":"A wider view adds context but cannot remove uncertainty."},"id":{"type":"multiple_choice","question":"Timeframe lebih panjang menghapus risiko pasar.","options":["Benar","Salah","Hanya untuk perusahaan besar","Hanya setelah breakout"],"answer":"Salah","explanation":"Pandangan lebih luas menambah konteks tetapi tidak menghapus ketidakpastian."}},
  {"en":{"type":"multiple_choice","question":"What should be named before comparing two similar patterns?","options":["The timeframe and surrounding context","Only the candle colour","The pattern name alone","A prediction that both agree"],"answer":"The timeframe and surrounding context","explanation":"The same shape can carry different context in another window."},"id":{"type":"multiple_choice","question":"Apa yang harus disebutkan sebelum membandingkan dua pola serupa?","options":["Timeframe dan konteks sekitar","Hanya warna candle","Nama pola saja","Prediksi bahwa keduanya sama"],"answer":"Timeframe dan konteks sekitar","explanation":"Bentuk sama dapat memiliki konteks berbeda pada jendela lain."}},
  {"en":{"type":"multiple_choice","question":"A daily chart and an intraday chart disagree about the apparent trend. What is safest?","options":["Describe the difference and inspect the timeframe before concluding","Choose the chart that supports the story","Average the two predictions","Assume the longer chart is always right"],"answer":"Describe the difference and inspect the timeframe before concluding","explanation":"Apparent disagreement can reflect different aggregation windows."},"id":{"type":"multiple_choice","question":"Grafik harian dan intraday tampak tidak sepakat tentang tren. Apa yang paling aman?","options":["Jelaskan perbedaannya dan periksa timeframe sebelum menyimpulkan","Pilih grafik yang mendukung cerita","Rata-ratakan kedua ramalan","Anggap grafik panjang selalu benar"],"answer":"Jelaskan perbedaannya dan periksa timeframe sebelum menyimpulkan","explanation":"Perbedaan yang tampak dapat mencerminkan jendela agregasi berbeda."}},
  {"en":{"type":"multiple_choice","question":"What does changing timeframe change first?","options":["The amount of detail visible in the observation","The underlying company facts","The probability of profit","The investor's risk capacity"],"answer":"The amount of detail visible in the observation","explanation":"Timeframe changes the lens, not the underlying facts or personal limits."},"id":{"type":"multiple_choice","question":"Apa yang pertama kali berubah saat timeframe diganti?","options":["Jumlah detail yang terlihat dalam pengamatan","Fakta dasar perusahaan","Probabilitas keuntungan","Kapasitas risiko investor"],"answer":"Jumlah detail yang terlihat dalam pengamatan","explanation":"Timeframe mengubah lensa, bukan fakta dasar atau batas pribadi."}}
]$json$::jsonb),
('decision-risk-reward', $json$[
  {"en":{"type":"multiple_choice","question":"A fictional idea shows Rp100,000 possible loss and Rp200,000 possible gain. What does 1:2 describe?","options":["Scenario magnitudes, not probability or guarantee","Guaranteed profit","Chance of success","A required personal trade"],"answer":"Scenario magnitudes, not probability or guarantee","explanation":"Risk/reward compares magnitudes; it does not predict probability."},"id":{"type":"multiple_choice","question":"Ide fiktif menunjukkan kemungkinan rugi Rp100.000 dan untung Rp200.000. Apa yang dijelaskan 1:2?","options":["Besaran skenario, bukan probabilitas atau jaminan","Keuntungan dijamin","Peluang berhasil","Transaksi pribadi wajib"],"answer":"Besaran skenario, bukan probabilitas atau jaminan","explanation":"Risiko/imbal hasil membandingkan besaran; bukan memprediksi probabilitas."}},
  {"en":{"type":"multiple_choice","question":"A favourable ratio can still lose money.","options":["True","False","Only when volume is low","Only outside Indonesia"],"answer":"True","explanation":"A ratio does not make the possible loss disappear."},"id":{"type":"multiple_choice","question":"Rasio yang tampak baik tetap dapat menghasilkan kerugian.","options":["Benar","Salah","Hanya saat volume rendah","Hanya di luar Indonesia"],"answer":"Benar","explanation":"Rasio tidak membuat kemungkinan rugi menghilang."}},
  {"en":{"type":"multiple_choice","question":"What should be checked before accepting a possible loss?","options":["Whether it fits essentials and the financial plan","Whether the story sounds exciting","Whether a friend agrees","Whether a ratio looks impressive"],"answer":"Whether it fits essentials and the financial plan","explanation":"A ratio cannot override personal financial boundaries."},"id":{"type":"multiple_choice","question":"Apa yang perlu diperiksa sebelum menerima kemungkinan rugi?","options":["Apakah sesuai dengan kebutuhan pokok dan rencana keuangan","Apakah ceritanya menarik","Apakah teman setuju","Apakah rasionya terlihat mengesankan"],"answer":"Apakah sesuai dengan kebutuhan pokok dan rencana keuangan","explanation":"Rasio tidak boleh mengalahkan batas keuangan pribadi."}},
  {"en":{"type":"multiple_choice","question":"A 1:3 ratio is best understood as what?","options":["A comparison of stated possible loss and gain","A three-times probability of success","A promise of three profitable trades","A substitute for research"],"answer":"A comparison of stated possible loss and gain","explanation":"The ratio describes a scenario relationship, not its likelihood."},"id":{"type":"multiple_choice","question":"Rasio 1:3 paling tepat dipahami sebagai apa?","options":["Perbandingan kemungkinan rugi dan untung yang disebutkan","Probabilitas keberhasilan tiga kali lipat","Janji tiga transaksi untung","Pengganti riset"],"answer":"Perbandingan kemungkinan rugi dan untung yang disebutkan","explanation":"Rasio menggambarkan hubungan skenario, bukan kemungkinannya."}},
  {"en":{"type":"multiple_choice","question":"Why write the possible loss before the possible gain?","options":["It keeps downside visible during the decision","It guarantees disciplined behaviour","It makes the gain more likely","It removes market uncertainty"],"answer":"It keeps downside visible during the decision","explanation":"Naming downside first supports a clearer boundary; it is not a guarantee."},"id":{"type":"multiple_choice","question":"Mengapa kemungkinan rugi ditulis sebelum kemungkinan untung?","options":["Agar sisi buruk tetap terlihat saat mengambil keputusan","Menjamin perilaku disiplin","Membuat keuntungan lebih mungkin","Menghapus ketidakpastian pasar"],"answer":"Agar sisi buruk tetap terlihat saat mengambil keputusan","explanation":"Menyebutkan sisi buruk lebih dulu membantu batas yang jelas; bukan jaminan."}}
]$json$::jsonb),
('decision-position-sizing', $json$[
  {"en":{"type":"multiple_choice","question":"Why can a smaller position protect a plan?","options":["It limits exposure if the thesis is wrong","It guarantees the thesis","It removes the need for a buffer","It turns volatility into income"],"answer":"It limits exposure if the thesis is wrong","explanation":"Size changes potential damage, not the truth of the thesis."},"id":{"type":"multiple_choice","question":"Mengapa posisi lebih kecil dapat melindungi rencana?","options":["Membatasi eksposur jika tesis salah","Menjamin tesis benar","Menghapus kebutuhan penyangga","Mengubah volatilitas menjadi pendapatan"],"answer":"Membatasi eksposur jika tesis salah","explanation":"Ukuran mengubah potensi dampak, bukan kebenaran tesis."}},
  {"en":{"type":"multiple_choice","question":"Money needed for rent, food, debt, or near-term goals is available risk capital.","options":["True","False","Only after saving","Only with diversification"],"answer":"False","explanation":"Essentials and near-term goals need protection."},"id":{"type":"multiple_choice","question":"Uang untuk sewa, makan, utang, atau tujuan dekat adalah modal risiko.","options":["Benar","Salah","Hanya setelah menabung","Hanya dengan diversifikasi"],"answer":"Salah","explanation":"Kebutuhan pokok dan tujuan dekat perlu dilindungi."}},
  {"en":{"type":"multiple_choice","question":"What should come before choosing exposure?","options":["Protect essentials and define tolerable loss","Choose the largest position","Copy the loudest opinion","Ignore the time horizon"],"answer":"Protect essentials and define tolerable loss","explanation":"Protect the plan first, then define exposure."},"id":{"type":"multiple_choice","question":"Apa yang dilakukan sebelum memilih eksposur?","options":["Lindungi kebutuhan pokok dan tentukan kerugian yang dapat ditanggung","Pilih posisi terbesar","Tiru opini paling keras","Abaikan horizon waktu"],"answer":"Lindungi kebutuhan pokok dan tentukan kerugian yang dapat ditanggung","explanation":"Lindungi rencana lebih dulu, lalu tentukan eksposur."}},
  {"en":{"type":"multiple_choice","question":"Two people can choose different position sizes because what differs?","options":["Their goals, time horizons, and ability to absorb loss","The market's guaranteed direction","The meaning of the ticker","The definition of diversification"],"answer":"Their goals, time horizons, and ability to absorb loss","explanation":"Position sizing is contextual, not a universal number."},"id":{"type":"multiple_choice","question":"Dua orang dapat memilih ukuran posisi berbeda karena apa?","options":["Tujuan, horizon waktu, dan kemampuan menanggung rugi mereka berbeda","Arah pasar yang dijamin","Arti ticker","Definisi diversifikasi"],"answer":"Tujuan, horizon waktu, dan kemampuan menanggung rugi mereka berbeda","explanation":"Ukuran posisi bersifat kontekstual, bukan angka universal."}},
  {"en":{"type":"multiple_choice","question":"What does position size control most directly?","options":["The amount of capital exposed to the idea","Whether the idea is correct","The asset's market price","The quality of an official source"],"answer":"The amount of capital exposed to the idea","explanation":"Size controls exposure; it cannot control the outcome."},"id":{"type":"multiple_choice","question":"Apa yang paling langsung dikendalikan oleh ukuran posisi?","options":["Jumlah modal yang terekspos pada ide","Apakah ide itu benar","Harga pasar aset","Kualitas sumber resmi"],"answer":"Jumlah modal yang terekspos pada ide","explanation":"Ukuran mengendalikan eksposur; bukan hasilnya."}}
]$json$::jsonb),
('decision-bias-and-narratives', $json$[
  {"en":{"type":"multiple_choice","question":"What is a useful response to confirmation bias?","options":["Write one observation that would weaken the belief","Collect only agreeing posts","Treat confidence as evidence","Ignore neutral sources"],"answer":"Write one observation that would weaken the belief","explanation":"A disconfirming condition makes a belief testable."},"id":{"type":"multiple_choice","question":"Apa respons berguna terhadap bias konfirmasi?","options":["Tuliskan satu pengamatan yang dapat melemahkan keyakinan","Kumpulkan hanya unggahan yang setuju","Anggap keyakinan sebagai bukti","Abaikan sumber netral"],"answer":"Tuliskan satu pengamatan yang dapat melemahkan keyakinan","explanation":"Kondisi penyangkal membuat keyakinan dapat diuji."}},
  {"en":{"type":"multiple_choice","question":"An official source automatically proves your interpretation is correct.","options":["True","False","Only for charts","Only for OJK sources"],"answer":"False","explanation":"A source provides evidence; interpretation still requires reasoning."},"id":{"type":"multiple_choice","question":"Sumber resmi otomatis membuktikan interpretasimu benar.","options":["Benar","Salah","Hanya untuk grafik","Hanya untuk sumber OJK"],"answer":"Salah","explanation":"Sumber memberi bukti; interpretasi tetap membutuhkan penalaran."}},
  {"en":{"type":"multiple_choice","question":"What should happen before deciding from a market story?","options":["State the story, seek disconfirmation, and check neutral evidence","Collect only confirming evidence","Decide from confidence","Skip source checking"],"answer":"State the story, seek disconfirmation, and check neutral evidence","explanation":"Make the narrative visible before testing it."},"id":{"type":"multiple_choice","question":"Apa yang dilakukan sebelum memutuskan berdasarkan cerita pasar?","options":["Sebutkan cerita, cari bukti penyangkal, dan periksa bukti netral","Kumpulkan hanya bukti yang setuju","Putuskan dari keyakinan","Lewati pemeriksaan sumber"],"answer":"Sebutkan cerita, cari bukti penyangkal, dan periksa bukti netral","explanation":"Buat narasinya terlihat sebelum mengujinya."}},
  {"en":{"type":"multiple_choice","question":"A popular narrative has three supporting posts and no stated counterexample. What is missing?","options":["A condition that could show the narrative is wrong","More excitement","A louder influencer","A guaranteed target"],"answer":"A condition that could show the narrative is wrong","explanation":"Without a counterexample, confirmation is difficult to challenge."},"id":{"type":"multiple_choice","question":"Narasi populer memiliki tiga unggahan pendukung tanpa contoh penyangkal. Apa yang kurang?","options":["Kondisi yang dapat menunjukkan narasi itu salah","Lebih banyak kegembiraan","Influencer yang lebih keras","Target yang dijamin"],"answer":"Kondisi yang dapat menunjukkan narasi itu salah","explanation":"Tanpa contoh penyangkal, konfirmasi sulit ditantang."}},
  {"en":{"type":"multiple_choice","question":"Why separate facts from interpretation?","options":["It makes the reasoning easier to inspect and update","It guarantees neutrality","It makes rumours official","It removes the need for evidence"],"answer":"It makes the reasoning easier to inspect and update","explanation":"Clear separation reduces the chance that a story hides its assumptions."},"id":{"type":"multiple_choice","question":"Mengapa fakta dipisahkan dari interpretasi?","options":["Agar penalaran lebih mudah diperiksa dan diperbarui","Menjamin netralitas","Membuat rumor menjadi resmi","Menghapus kebutuhan akan bukti"],"answer":"Agar penalaran lebih mudah diperiksa dan diperbarui","explanation":"Pemisahan yang jelas mengurangi kemungkinan asumsi tersembunyi dalam cerita."}}
]$json$::jsonb),
('decision-thesis-invalidation', $json$[
  {"en":{"type":"multiple_choice","question":"What makes an invalidation rule useful?","options":["It names observable evidence that triggers reassessment","It guarantees profit","It changes after every move","It protects a story from challenge"],"answer":"It names observable evidence that triggers reassessment","explanation":"An invalidation rule creates a boundary for updating a thesis."},"id":{"type":"multiple_choice","question":"Apa yang membuat aturan pembatalan berguna?","options":["Menyebutkan bukti yang dapat diamati untuk memicu penilaian ulang","Menjamin keuntungan","Berubah setiap pergerakan","Melindungi cerita dari tantangan"],"answer":"Menyebutkan bukti yang dapat diamati untuk memicu penilaian ulang","explanation":"Aturan pembatalan membuat batas untuk memperbarui tesis."}},
  {"en":{"type":"multiple_choice","question":"Changing a thesis after new evidence appears can be disciplined decision-making.","options":["True","False","Only after a profit","Only when a chart is flat"],"answer":"True","explanation":"A thesis is a working explanation that should respond to evidence."},"id":{"type":"multiple_choice","question":"Mengubah tesis setelah bukti baru muncul dapat menjadi keputusan disiplin.","options":["Benar","Salah","Hanya setelah untung","Hanya saat grafik datar"],"answer":"Benar","explanation":"Tesis adalah penjelasan kerja yang merespons bukti."}},
  {"en":{"type":"multiple_choice","question":"What should be written before the outcome is known?","options":["The thesis and the evidence that would weaken it","A guaranteed future price","A story explaining every outcome","A promise of profit"],"answer":"The thesis and the evidence that would weaken it","explanation":"Writing the boundary early reduces hindsight stories."},"id":{"type":"multiple_choice","question":"Apa yang perlu ditulis sebelum hasil diketahui?","options":["Tesis dan bukti yang akan melemahkannya","Harga masa depan yang dijamin","Cerita untuk menjelaskan semua hasil","Janji keuntungan"],"answer":"Tesis dan bukti yang akan melemahkannya","explanation":"Menulis batas lebih awal mengurangi cerita hindsight."}},
  {"en":{"type":"multiple_choice","question":"Which is an observable invalidation condition?","options":["The stated evidence no longer appears after the defined review period","I feel less excited","Someone online sounds confident","The ticker is popular"],"answer":"The stated evidence no longer appears after the defined review period","explanation":"A useful condition can be checked against evidence and timing."},"id":{"type":"multiple_choice","question":"Mana yang merupakan kondisi pembatalan yang dapat diamati?","options":["Bukti yang disebutkan tidak lagi muncul setelah periode peninjauan yang ditetapkan","Saya tidak lagi bersemangat","Seseorang online terdengar percaya diri","Ticker populer"],"answer":"Bukti yang disebutkan tidak lagi muncul setelah periode peninjauan yang ditetapkan","explanation":"Kondisi yang berguna dapat diperiksa terhadap bukti dan waktu."}},
  {"en":{"type":"multiple_choice","question":"What should happen when an invalidation condition appears?","options":["Pause, record the evidence, and reassess the thesis","Move the condition so the thesis survives","Ignore it until a profit appears","Treat it as a guaranteed sell signal"],"answer":"Pause, record the evidence, and reassess the thesis","explanation":"Reassessment is a reasoning step, not an automatic trade instruction."},"id":{"type":"multiple_choice","question":"Apa yang dilakukan saat kondisi pembatalan muncul?","options":["Berhenti, catat bukti, dan nilai ulang tesis","Pindahkan kondisinya agar tesis bertahan","Abaikan sampai untung","Anggap sebagai sinyal jual yang dijamin"],"answer":"Berhenti, catat bukti, dan nilai ulang tesis","explanation":"Penilaian ulang adalah langkah penalaran, bukan instruksi transaksi otomatis."}}
]$json$::jsonb)
)
INSERT INTO public.content_variants (lesson_id, variant_type, body, body_id, difficulty, topic_tag, is_active)
SELECT l.id, 'question', item->'en', item->'id', 'advanced', 'visual_applied', TRUE
FROM authored a
JOIN public.lessons l ON l.slug=a.slug AND l.is_published
CROSS JOIN LATERAL jsonb_array_elements(a.questions) item;

DO $$
DECLARE
  lesson_count INT;
  variant_count INT;
  source_count INT;
  bad_count INT;
BEGIN
  SELECT COUNT(*) INTO lesson_count
  FROM public.lessons l JOIN public.topics t ON t.id=l.topic_id
  WHERE t.chapter='Decision Analysis Lab' AND l.is_published;

  SELECT COUNT(*) INTO variant_count
  FROM public.content_variants v JOIN public.lessons l ON l.id=v.lesson_id JOIN public.topics t ON t.id=l.topic_id
  WHERE t.chapter='Decision Analysis Lab' AND l.is_published
    AND v.variant_type='question' AND v.topic_tag='visual_applied' AND v.is_active;

  SELECT COUNT(DISTINCT l.id) INTO source_count
  FROM public.lesson_sources ls JOIN public.lessons l ON l.id=ls.lesson_id JOIN public.topics t ON t.id=l.topic_id
  JOIN public.sources s ON s.id=ls.source_id
  WHERE t.chapter='Decision Analysis Lab' AND l.is_published AND ls.is_primary
    AND s.source_tier=1 AND s.status='verified' AND s.synopsis IS NOT NULL AND s.synopsis_id IS NOT NULL;

  SELECT COUNT(*) INTO bad_count
  FROM public.content_variants v JOIN public.lessons l ON l.id=v.lesson_id JOIN public.topics t ON t.id=l.topic_id
  WHERE t.chapter='Decision Analysis Lab' AND l.is_published
    AND v.variant_type='question' AND v.topic_tag='visual_applied' AND v.is_active
    AND (v.body->>'question' IS NULL OR v.body->>'answer' IS NULL
      OR NOT (v.body->'options' ? (v.body->>'answer'))
      OR v.body_id->>'question' IS NULL OR v.body_id->>'answer' IS NULL
      OR NOT (v.body_id->'options' ? (v.body_id->>'answer')));

  IF lesson_count<>8 OR variant_count<>40 OR source_count<>8 OR bad_count<>0 THEN
    RAISE EXCEPTION 'KO-446 coverage mismatch: lessons %, variants %, sources %, invalid %', lesson_count, variant_count, source_count, bad_count;
  END IF;
END $$;

COMMIT;
